//! On-demand prices per region (RULES 121): `data/prices/<provider>/<region>.csv`, one file for each
//! region of AWS, Azure and GCP, generated by `scripts/gen-instances.mjs` and embedded. The cost
//! estimate reads a type's price in the region the person picked; the default-region price also
//! sits in `data/instances.csv` ([`crate::instances::Instance::price_micro_usd_hr`]).
//!
//! **Every price is an estimate**: the on-demand Linux list price an hour, in micro-USD (1,000,000
//! = 1 dollar, an integer so sums do not drift), as the catalogue carried it on the date in the
//! file header. Reserved and spot prices, Windows, egress, storage and managed-service fees are not
//! here. A type with no price in a region is absent from that region's file.

use std::sync::OnceLock;

use crate::config::StorageClass;

use crate::prices_data::FILES;

/// A default region per provider (what `data/instances.csv` carries): AWS `us-east-1`, Azure
/// `us-east` (East US), GCP `us-central1`.
pub const DEFAULT_REGIONS: [(&str, &str); 3] = [
    ("aws", "us-east-1"),
    ("azure", "us-east"),
    ("gcp", "us-central1"),
];

/// A parsed region file: `(type name, micro-USD an hour)`, sorted by name.
type Prices = Vec<(&'static str, u32)>;

/// Every region file, parsed on first use, in the order of [`FILES`].
fn parsed() -> &'static [OnceLock<Prices>] {
    static CELLS: OnceLock<Vec<OnceLock<Prices>>> = OnceLock::new();
    CELLS.get_or_init(|| FILES.iter().map(|_| OnceLock::new()).collect())
}

/// The regions of `provider` (`aws`, `azure` or `gcp`), sorted.
#[must_use]
pub fn regions(provider: &str) -> Vec<&'static str> {
    FILES
        .iter()
        .filter(|(p, _, _)| *p == provider)
        .map(|(_, r, _)| *r)
        .collect()
}

/// The prices of `region` of `provider`, sorted by type name (`provider/type`, lower case); `None`
/// for a region the table does not have.
#[must_use]
pub fn region_table(provider: &str, region: &str) -> Option<&'static [(&'static str, u32)]> {
    let i = FILES
        .iter()
        .position(|(p, r, _)| *p == provider && *r == region)?;
    let table = parsed()[i].get_or_init(|| {
        FILES[i]
            .2
            .lines()
            .filter(|l| !l.is_empty() && !l.starts_with('#'))
            .map(|l| {
                let (name, price) = l.split_once(',').expect("a name and a price");
                (name, price.parse().expect("the price is a number"))
            })
            .collect()
    });
    Some(table)
}

/// The price an hour of the type `name` (`aws/m5.large`) in `region`, in micro-USD; `None` when the
/// region is not the provider's, or the type has no price there.
#[must_use]
pub fn price_micro_usd_hr(region: &str, name: &str) -> Option<u32> {
    let key = name.trim().to_ascii_lowercase();
    let provider = key.split_once('/')?.0;
    let table = region_table(provider, region)?;
    table
        .binary_search_by(|(n, _)| (*n).cmp(key.as_str()))
        .ok()
        .map(|i| table[i].1)
}

/// What an object store costs in a region (`data/storage-prices.csv`, RULES 123): Standard class,
/// first tier, in micro-USD (an integer so sums do not drift).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct StoragePrice {
    /// One GB kept for a month.
    pub gb_month: u32,
    /// 1,000 write requests (PUT, COPY, POST, LIST).
    pub write_per_1k: u32,
    /// 1,000 read requests (GET).
    pub read_per_1k: u32,
    /// One GB retrieved: 0 for Standard, the fee of a colder class (RULES 128).
    pub retrieval_per_gb: u32,
}

/// One row of the storage price file: `(provider, region, price)`.
pub type StorageRow = (&'static str, &'static str, StoragePrice);

const STORAGE_CSV: &str = include_str!("../data/storage-prices.csv");

/// Every row of the storage price file, sorted by provider then region.
#[must_use]
pub fn storage_rows() -> &'static [StorageRow] {
    static ROWS: OnceLock<Vec<StorageRow>> = OnceLock::new();
    ROWS.get_or_init(|| {
        STORAGE_CSV
            .lines()
            .filter(|l| !l.is_empty() && !l.starts_with('#'))
            .map(|l| {
                let mut f = l.split(',');
                let mut next = || f.next().expect("a csv field");
                let (provider, region) = (next(), next());
                let mut n = || next().parse::<u32>().expect("a number");
                let price = StoragePrice {
                    gb_month: n(),
                    write_per_1k: n(),
                    read_per_1k: n(),
                    retrieval_per_gb: 0,
                };
                (provider, region, price)
            })
            .collect()
    })
}

/// One row of the colder-class price file: `(provider, region, class, price)`.
pub type StorageClassRow = (&'static str, &'static str, StorageClass, StoragePrice);

const STORAGE_CLASS_CSV: &str = include_str!("../data/storage-classes.csv");

/// Every row of the colder-class price file (`data/storage-classes.csv`, RULES 128): `infrequent`,
/// `cold` and `archive` for each provider and region that sells them. Standard is [`storage_rows`].
#[must_use]
pub fn storage_class_rows() -> &'static [StorageClassRow] {
    static ROWS: OnceLock<Vec<StorageClassRow>> = OnceLock::new();
    ROWS.get_or_init(|| {
        STORAGE_CLASS_CSV
            .lines()
            .filter(|l| !l.is_empty() && !l.starts_with('#'))
            .map(|l| {
                let mut f = l.split(',');
                let mut next = || f.next().expect("a csv field");
                let (provider, region, class) = (next(), next(), next());
                let class = match class {
                    "infrequent" => StorageClass::Infrequent,
                    "cold" => StorageClass::Cold,
                    "archive" => StorageClass::Archive,
                    other => panic!("storage-classes.csv: unknown class {other}"),
                };
                let mut n = || next().parse::<u32>().expect("a number");
                let price = StoragePrice {
                    gb_month: n(),
                    write_per_1k: n(),
                    read_per_1k: n(),
                    retrieval_per_gb: n(),
                };
                (provider, region, class, price)
            })
            .collect()
    })
}

/// The object-store price of `class` of `provider` in `region`: [`storage_price`] for Standard, else
/// the colder-class row; `None` when the cloud does not sell that class there.
#[must_use]
pub fn storage_class_price(
    provider: &str,
    region: &str,
    class: StorageClass,
) -> Option<StoragePrice> {
    if class == StorageClass::Standard {
        return storage_price(provider, region);
    }
    storage_class_rows()
        .iter()
        .find(|(p, r, c, _)| *p == provider && *r == region && *c == class)
        .map(|(_, _, _, price)| *price)
}

/// Every location that has an object-store price for `provider`, in file order: its regions and, for
/// `gcp`, the predefined dual- and multi-regions. Not the `*` row.
#[must_use]
pub fn storage_locations(provider: &str) -> Vec<&'static str> {
    storage_rows()
        .iter()
        .filter(|(p, r, _)| *p == provider && *r != "*")
        .map(|(_, r, _)| *r)
        .collect()
}

/// The object-store price of `provider` (`aws` S3, `azure` Blob, `gcp` Cloud Storage) in `region`.
/// A row for region `*` would answer for every region of its provider (none today).
#[must_use]
pub fn storage_price(provider: &str, region: &str) -> Option<StoragePrice> {
    let rows = storage_rows();
    let hit = |r: &str| rows.iter().find(|(p, g, _)| *p == provider && *g == r);
    hit(region).or_else(|| hit("*")).map(|(_, _, p)| *p)
}

/// The price an hour of a managed cache class (`aws/cache.m5.large`, `ElastiCache`) in the AWS
/// `region`, in micro-USD (on-demand): Valkey's own price for the `valkey` flavor (20% below Redis
/// OSS), else Redis OSS's (Memcached is the same price); `None` when the class has no price for
/// that engine there (the newest Graviton classes are Valkey-only in some regions).
#[must_use]
pub fn managed_cache_price_micro_usd_hr(
    flavor: Option<crate::config::CacheFlavor>,
    region: &str,
    name: &str,
) -> Option<u32> {
    let key = name.trim().to_ascii_lowercase();
    let provider = if flavor == Some(crate::config::CacheFlavor::Valkey) {
        "aws-elasticache-valkey"
    } else {
        "aws-elasticache"
    };
    let table = region_table(provider, region)?;
    table
        .binary_search_by(|(n, _)| (*n).cmp(key.as_str()))
        .ok()
        .map(|i| table[i].1)
}

/// The price an hour of a managed database class (`aws/db.m5.large`) running `engine` in the AWS
/// `region`, in micro-USD (single-AZ, on-demand, RULES 122); `None` when the engine has no price
/// for that class there. Each engine has its own files (`aws-rds-<engine>`).
#[must_use]
pub fn managed_price_micro_usd_hr(
    engine: crate::config::DbEngine,
    region: &str,
    name: &str,
) -> Option<u32> {
    let key = name.trim().to_ascii_lowercase();
    // Azure SQL's classes are `azure/db.*` and have their own folder (RULES 131)
    let provider = if engine == crate::config::DbEngine::AzureSql {
        "azure-sql".to_string()
    } else {
        format!("aws-rds-{}", engine.word())
    };
    let table = region_table(&provider, region)?;
    table
        .binary_search_by(|(n, _)| (*n).cmp(key.as_str()))
        .ok()
        .map(|i| table[i].1)
}

/// What sending data out to the internet costs in a region (`data/egress.csv`, RULES 131): the
/// first-tier price, in micro-USD, and the monthly allowance that is free.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct EgressPrice {
    /// One GB sent out, micro-USD.
    pub micro_usd_per_gb: u32,
    /// GB a month that cost nothing.
    pub free_gb: u32,
}

const EGRESS_CSV: &str = include_str!("../data/egress.csv");

/// The internet-egress price of `provider` (`aws`, `azure`, `gcp`) in `region`. A row for region `*`
/// answers for every region of its provider (Google's headline, today).
#[must_use]
pub fn egress_price(provider: &str, region: &str) -> Option<EgressPrice> {
    static ROWS: OnceLock<Vec<(&'static str, &'static str, EgressPrice)>> = OnceLock::new();
    let rows = ROWS.get_or_init(|| {
        EGRESS_CSV
            .lines()
            .filter(|l| !l.is_empty() && !l.starts_with('#'))
            .map(|l| {
                let mut f = l.split(',');
                let mut next = || f.next().expect("a csv field");
                let (p, r) = (next(), next());
                let mut n = || next().parse::<u32>().expect("a number");
                let price = EgressPrice {
                    micro_usd_per_gb: n(),
                    free_gb: n(),
                };
                (p, r, price)
            })
            .collect()
    });
    let hit = |r: &str| rows.iter().find(|(p, g, _)| *p == provider && *g == r);
    hit(region).or_else(|| hit("*")).map(|(_, _, p)| *p)
}

const PER_USE_CSV: &str = include_str!("../data/per-use.csv");

/// A pay-per-use price (`data/per-use.csv`, RULES 131), first tier, in micro-USD: `lambda_request`
/// and `apigw_request` for a million requests, `lambda_gb_second` for a thousand GB-seconds; `None`
/// where the cloud does not sell the service in `region`.
#[must_use]
pub fn per_use_price(service: &str, region: &str) -> Option<u32> {
    PER_USE_CSV
        .lines()
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .find_map(|l| {
            let mut f = l.split(',');
            (f.next()? == service && f.next()? == region)
                .then(|| f.next()?.parse().ok())
                .flatten()
        })
}
